class Solution {
    public int countPairs(int[] nums, int target) {
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        int count = 0;
        for (int v : nums) {
            if (seen.contains(target - v)) {
                count++;
            }
            seen.add(v);
        }
        return count;
    }
}

class Solution {
    public int countPairs(int[] nums, int target) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length - 1; j++) {
                if (nums[i] + nums[j] == target) {
                    count++;
                }
            }
        }
        return count;
    }
}
